typedef struct { time_t effective; Terms terms; } Version;
typedef struct { ContractId id; Version *versions; size_t n, cap; } Contract;

const Terms *terms_as_of(const Contract *c, time_t on) {
    size_t lo = 0, hi = c->n;                      /* versions sorted ascending */
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (c->versions[mid].effective <= on) lo = mid + 1; else hi = mid;
    }
    return lo ? &c->versions[lo - 1].terms : NULL;  /* NULL = before first version */
}
